 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    marks = {v for v in counts if v != background}
    # The sparse non-background marks are joined by straight horizontal and
    # vertical segments; preserve mark cells and color only intervening cells.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] in marks]
        if len(positions) >= 2:
            for c in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] in marks]
        if len(positions) >= 2:
            for r in range(min(positions), max(positions) + 1):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
